#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn true_case() {
        assert!(is_clean_palindrome("Was it a car, or a cat I saw?"));
    }

    #[test]
    fn false_case() {
        assert!(!is_clean_palindrome("race a car"));
    }

    #[test]
    fn only_punctuation() {
        assert!(is_clean_palindrome(" ,.!"));
        assert!(is_clean_palindrome(""));
    }

    #[test]
    fn digits() {
        assert!(!is_clean_palindrome("1a2"));
        assert!(is_clean_palindrome("12:21"));
    }

    #[test]
    fn mixed_case() {
        assert!(is_clean_palindrome("No 'x' in Nixon"));
    }
}
